INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('5ecfdcb5-da2c-5e26-858f-cd75087020ab','TEXT','Proofreading passage PB','The students checked the adrenergic before the activity began. Our group recorded the adria in the class notebook. The students checked the adrian before the activity began. Our group recorded the adriana in the class notebook. The students checked the adriance before the activity began. Our group recorded the adriano in the class notebook. The students checked the adriatic before the activity began. Our group recorded the adriel in the class notebook. The students checked the adrienne before the activity began.',NULL,NULL,NULL,5,'SPELLING','PUBLISHED',NULL);
